class ResidualBlock(nn.Module):
    def __init__(self, dim, activation):
        super().__init__()
        self.fc1 = nn.Linear(dim, dim)
        self.ln1 = nn.LayerNorm(dim)
        self.act1 = activation
        self.fc2 = nn.Linear(dim, dim)
        self.ln2 = nn.LayerNorm(dim)
        self.act2 = activation

    def forward(self, x):
        residual = x
        x = self.fc1(x)
        x = self.ln1(x)
        x = self.act1(x)
        x = self.fc2(x)
        x = self.ln2(x)
        return self.act2(x + residual)

class ActorCritic(nn.Module):
    def __init__(self,  num_actor_obs,
                        num_critic_obs,
                        num_actions,
                        actor_hidden_dims=[256, 256, 256],
                        critic_hidden_dims=[256, 256, 256],
                        init_noise_std=1.0,
                        activation = nn.ELU(),
                        **kwargs):
        if kwargs:
            print("ActorCritic.__init__ got unexpected arguments, which will be ignored: " + str([key for key in kwargs.keys()]))
        super(ActorCritic, self).__init__()

        activation = nn.SiLU() # Override with Swish for better performance
        hidden_dim = 256

        actor_layers = [
            nn.Linear(num_actor_obs, hidden_dim),
            nn.LayerNorm(hidden_dim),
            activation,
            ResidualBlock(hidden_dim, activation),
            ResidualBlock(hidden_dim, activation),
            nn.Linear(hidden_dim, num_actions)
        ]
        self.actor = nn.Sequential(*actor_layers)

        critic_layers = [
            nn.Linear(num_critic_obs, hidden_dim),
            nn.LayerNorm(hidden_dim),
            activation,
            ResidualBlock(hidden_dim, activation),
            ResidualBlock(hidden_dim, activation),
            nn.Linear(hidden_dim, 1)
        ]
        self.critic = nn.Sequential(*critic_layers)

        print(f"Actor ResNet: {self.actor}")
        print(f"Critic ResNet: {self.critic}")

        self.std = nn.Parameter(init_noise_std * torch.ones(num_actions))
        self.distribution = None
        Normal.set_default_validate_args = False

        self.apply(self.init_weights_custom)
        nn.init.orthogonal_(self.actor[-1].weight, gain=0.01)
        nn.init.orthogonal_(self.critic[-1].weight, gain=0.01)

    def init_weights_custom(self, m):
        if isinstance(m, nn.Linear):
            nn.init.orthogonal_(m.weight, gain=1.0)
            if m.bias is not None:
                nn.init.zeros_(m.bias)

    @staticmethod
    def init_weights(sequential, scales):
        pass

    def reset(self, dones=None):
        pass

    def forward(self):
        raise NotImplementedError

    @property
    def action_mean(self):
        return self.distribution.mean

    @property
    def action_std(self):
        return self.distribution.stddev

    @property
    def entropy(self):
        return self.distribution.entropy().sum(dim=-1)

    def update_distribution(self, observations):
        mean = self.actor(observations)
        self.distribution = Normal(mean, mean*0. + self.std)

    def act(self, observations, **kwargs):
        self.update_distribution(observations)
        return self.distribution.sample()

    def get_actions_log_prob(self, actions):
        return self.distribution.log_prob(actions).sum(dim=-1)

    def act_inference(self, observations):
        actions_mean = self.actor(observations)
        return actions_mean

    def evaluate(self, critic_observations, **kwargs):
        value = self.critic(critic_observations)
        return value

